const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const antarctica = ee.Geometry.Point([0, -90]).buffer(3500000); // Buffer around the South Pole to cover Antarctica
    const dateOct = '2021-10-07';
    const dateJan = '2021-01-01';
    const ozoneHoleThresholdDU = 220;

    // 2. Data Acquisition
    const collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_O3')
        .select(['O3_column_number_density', 'qa_value']);

    // Function to process an image for a given date
    const getOzoneHoleArea = function(dateString) {
        const imageCol = collection.filterDate(dateString, ee.Date(dateString).advance(1, 'day'));

        // C1 Check: No images found
        if (imageCol.size().getInfo() === 0) {
            return {area: null, pixelCount: null, status: 'C1', date: dateString};
        }

        const image = imageCol.first();
        const qualityMask = image.select('qa_value').gt(0.5);
        const ozone = image.select('O3_column_number_density').updateMask(qualityMask);

        // Conversion from mol/m^2 to Dobson Units (DU). 1 DU = 2.69e16 molecules/cm^2.
        // The GEE catalog provides a conversion: 1 mol/m^2 is approximately 2241.1 DU
        const ozoneDU = ozone.multiply(2241.1);

        // Define the ozone hole as areas with < 220 DU
        const holeMask = ozoneDU.lt(ozoneHoleThresholdDU);

        // Calculate the area of the hole
        const pixelArea = ee.Image.pixelArea();
        const holeAreaImage = holeMask.multiply(pixelArea);

        const stats = holeAreaImage.reduceRegion({
            reducer: ee.Reducer.sum().combine({
                reducer2: ee.Reducer.count(),
                sharedInputs: true
            }),
            geometry: antarctica,
            scale: 5000, // Use a coarse scale to avoid timeout
            maxPixels: 1e9
        });

        const area = stats.get('O3_column_number_density_sum');
        const count = stats.get('O3_column_number_density_count');

        return {area: area.getInfo(), pixelCount: count.getInfo(), status: 'OK', date: dateString};
    };

    // 3. Processing and Calculation
    const resultOct = getOzoneHoleArea(dateOct);
    const resultJan = getOzoneHoleArea(dateJan);

    // 4. Validation & Final Answer
    if (resultOct.status === 'C1' || resultJan.status === 'C1') {
        console.log(`No image found for Oct 2021: ${resultOct.status === 'C1'}`);
        console.log(`No image found for Jan 2021: ${resultJan.status === 'C1'}`);
        console.log('A');
        return;
    }

    // C2 Check: No valid pixels after masking
    if (resultOct.pixelCount === 0 || resultJan.pixelCount === 0) {
        console.log(`October 2021 Valid Pixels: ${resultOct.pixelCount}`);
        console.log(`January 2021 Valid Pixels: ${resultJan.pixelCount}`);
        console.log('C2');
        return;
    }

    // C3 Check: Calculation failed
    if (resultOct.area === null || resultJan.area === null) {
        console.log(`October 2021 Area Calculation: ${resultOct.area}`);
        console.log(`January 2021 Area Calculation: ${resultJan.area}`);
        console.log('C3');
        return;
    }

    const areaOct_km2 = resultOct.area / 1e6; // Convert m^2 to km^2
    const areaJan_km2 = resultJan.area / 1e6;

    console.log(`Ozone Hole Area (Oct 7, 2021): ${areaOct_km2.toLocaleString('en-US', { maximumFractionDigits: 0 })} km²`);
    console.log(`Ozone Hole Area (Jan 1, 2021): ${areaJan_km2.toLocaleString('en-US', { maximumFractionDigits: 0 })} km²`);
    console.log(`Valid pixels (Oct): ${resultOct.pixelCount}, (Jan): ${resultJan.pixelCount}`);

    if (areaOct_km2 > areaJan_km2) {
        console.log('A');
    } else {
        console.log('B');
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(e => {
    console.error(e);
    console.log('D');
});
